window.ChapterSpec={"scope": "原创交互导读，覆盖本章主节与精选定量模型；不复刻原书全文、原图或全部推导。各实验的背景与近似分别声明，不组成一套统一研究模拟。伴读生成可复制的参数化问题，未提供在线模型回答。", "number": 10, "title": "恒星族与化学演化", "headline": "把一群恒星，\n读成一段历史", "lede": "年龄、初始质量和元素丰度一起决定星系的光。把光度预算与质量、金属预算放在同一条叙事里。", "pages": [449, 494], "labs": [{"id": "lifetime", "model": "lifetime", "title": "用主序寿命，读一群恒星的年龄", "intro": "质量改变燃料与消耗速率；将单星寿命与给定星群年龄的主序转折质量放在一起看。", "params": [{"key": "m", "label": "单星质量（M☉）", "min": 0.1, "max": 30, "step": 0.1, "value": 1, "digits": 2}, {"key": "age", "label": "星群年龄（Gyr）", "min": 0.01, "max": 12, "step": 0.01, "value": 5, "digits": 2}], "values": ["单星主序寿命（Gyr）", "转折质量（M☉）", "m³·⁵ 光度示意 / L☉"], "pages": [462, 463], "formula": "tMS=[2500+670m²·⁵+m⁴·⁵]/[0.033m¹·⁵+0.35m⁴·⁵] Myr", "assumptions": "原书式10.72的近太阳丰度寿命拟合，0.08–100M☉内求转折。显示L∝m³·⁵只是独立教学标度，不是该拟合自带精确光度。未加入旋转、双星或完整演化轨迹。", "scene": true, "ref": "10.1 · MBW (2010) pp.462–463", "formulaTex": ["\\frac{t_{\\mathrm{MS}}}{\\mathrm{Myr}}=\\frac{2500+670m^{2.5}+m^{4.5}}{0.033m^{1.5}+0.35m^{4.5}}", "m=\\frac{M_\\star}{M_\\odot}"]}, {"id": "ssp", "model": "ssp", "title": "一场形成之后，哪些主序星仍在发光", "intro": "固定初始质量，只让寿命短的恒星离开主序。区分仍在主序的质量份额与总星群光度。", "params": [{"key": "age", "label": "年龄（Gyr）", "min": 0.01, "max": 12, "step": 0.01, "value": 1, "digits": 2}, {"key": "slope", "label": "单幂律IMF指数", "min": 1.5, "max": 3, "step": 0.05, "value": 2.35, "digits": 2}], "values": ["转折质量（M☉）", "主序 L / 初始M（太阳单位）", "仍在主序的初始质量份额（%）"], "pages": [470, 474], "formula": "LMS(t)=∫₀·₁^mTO C m⁻ˢ m³·⁵ dm<br>∫₀·₁¹⁰⁰ C m¹⁻ˢ dm=1", "assumptions": "仅主序星加权模型，遗漏巨星、AGB、双星、遗迹光、金属丰度与真实恒星谱。因此晚期光度不能代替SPS数据库；离开主序的质量也不等于已经全部回到气体。", "scene": true, "ref": "10.2 · MBW (2010) pp.470–474", "sweep": "age", "formulaTex": ["\\frac{L_{\\mathrm{MS}}(t)}{L_\\odot}=\\int_{0.1}^{m_{\\mathrm{TO}}}Cm^{-s}m^{3.5}\\,dm", "\\int_{0.1}^{100}Cm^{1-s}\\,dm=1"]}, {"id": "sfh", "model": "sfh", "title": "光更年轻，还是恒星质量更年轻", "intro": "把指数形成史与指定的光度响应核卷积，比较质量和光度的年龄权重。", "params": [{"key": "age", "label": "系统持续形成时间（Gyr）", "min": 1, "max": 12, "step": 0.1, "value": 8, "digits": 2}, {"key": "sf", "label": "形成史 e折时间（Gyr）", "min": 0.2, "max": 8, "step": 0.1, "value": 3, "digits": 2}, {"key": "light", "label": "光度响应 e折时间（Gyr）", "min": 0.1, "max": 3, "step": 0.1, "value": 0.5, "digits": 2}], "values": ["质量加权平均年龄（Gyr）", "光度加权平均年龄（Gyr）", "相对光响应（形成质量归一）"], "pages": [471, 474], "formula": "L(t)=∫ψ(t′) lSSP(t−t′)dt′<br>ψ∝exp(−t′/τSF)，lSSP(age)=exp(−age/τL)", "assumptions": "总形成质量归一化为1，两个指数函数都是明确指定的教学形状。曲线权重各自面积归一，光响应不对应实际滤镜；不能从此推断观测年龄精度。 响应核在年龄为0时定义为1，未指定实际波段或太阳光度单位。", "scene": false, "ref": "10.3 · MBW (2010) pp.471–474", "formulaTex": ["L(t)=\\int_0^t\\psi(t')\\,\\ell_{\\mathrm{SSP}}(t-t')\\,dt'", "\\psi(t')\\propto e^{-t'/\\tau_{\\mathrm{SF}}}", "\\ell_{\\mathrm{SSP}}(a)=e^{-a/\\tau_L}"]}, {"id": "dust", "model": "dust", "title": "同一束光，被尘埃怎样改写", "intro": "比较单温黑体与指定前景屏幕后的连续谱。尘埃会同时改变颜色和通量，而不必改变恒星的真实年龄。", "params": [{"key": "T", "label": "黑体温度（K）", "min": 4000, "max": 12000, "step": 100, "value": 6000, "digits": 2}, {"key": "Av", "label": "V 波段消光（mag）", "min": 0, "max": 3, "step": 0.05, "value": 1, "digits": 2}], "values": ["B 波段消光（mag）", "窄带 E(B−V)（mag）", "显示波段直达光损失（%）"], "pages": [476, 484], "formula": "Fλ,out=Fλ,in 10⁻⁰·⁴Aλ<br>Aλ=AV(λ/0.55μm)⁻¹", "assumptions": "单温黑体不是星族光谱。积分直达光损失只涵盖0.15–2.5μm；消光包含吸收和散射出视线，模型未分离两者，因此该损失不等于被吸收能量，也未计算红外再辐射。B/V用0.44/0.55μm窄带近似；真实衰减还依赖混合几何、散射和尘埃性质。 A_B表示B波段消光，不是AB星等系统；E(B−V)=A_B−A_V。", "scene": false, "ref": "10.3 · MBW (2010) pp.476–484", "formulaTex": ["F_{\\lambda,\\mathrm{out}}=F_{\\lambda,\\mathrm{in}}10^{-0.4A_\\lambda}", "A_\\lambda=A_V\\left(\\frac\\lambda{0.55\\,\\mu\\mathrm m}\\right)^{-1}"]}, {"id": "closed", "model": "closed", "title": "封闭箱里，气体越少越富金属", "intro": "按永久锁定的恒星质量定义产额，在同一个封闭预算中比较气体与恒星的平均丰度。", "params": [{"key": "mu", "label": "Mg / 初始气体质量", "min": 0.02, "max": 1, "step": 0.01, "value": 0.3, "digits": 2}, {"key": "yield", "label": "净产额 y", "min": 0.005, "max": 0.03, "step": 0.001, "value": 0.02, "digits": 3}], "values": ["气体 Z", "质量加权恒星平均 Z", "锁定质量 / 初始质量（%）"], "pages": [486, 490], "formula": "Z=y ln(1/μ)<br>⟨Z*⟩=y[1+μ lnμ/(1−μ)]", "assumptions": "初始Z=0、瞬时回收与均匀混合，无流入流出。y按永久锁定质量定义，非每单位总形成质量；金属质量分数Z不是直接的[Fe/H]。 μ=1时没有已锁定恒星，恒星平均金属丰度不定义；0仅是从有恒星侧趋近的极限。", "scene": false, "ref": "10.4 · MBW (2010) pp.486–490", "formulaTex": ["Z=y\\ln\\frac1\\mu", "\\langle Z_\\star\\rangle=y\\left(1+\\frac{\\mu\\ln\\mu}{1-\\mu}\\right)"]}, {"id": "leaky", "model": "leaky", "title": "同样的产额，外流为何降低有效产额", "intro": "固定回流率，改变随形成率流出的质量，检查气体、恒星与外流的完整质量账。", "params": [{"key": "mu", "label": "Mg / 初始气体质量", "min": 0.02, "max": 1, "step": 0.01, "value": 0.3, "digits": 2}, {"key": "loading", "label": "W / Ψ 的质量负载 λ", "min": 0, "max": 5, "step": 0.1, "value": 1, "digits": 2}, {"key": "yield", "label": "净产额 y", "min": 0.005, "max": 0.03, "step": 0.001, "value": 0.02, "digits": 3}], "values": ["气体 Z", "锁定恒星 / 初始质量（%）", "外流 / 初始质量（%）"], "pages": [490, 491], "formula": "η=λ/(1−R)，R=0.4<br>Z=y ln(1/μ)/(1+η)<br>Mlocked/M₀=(1−μ)/(1+η)，Mout=ηMlocked", "assumptions": "外流与星际气体同丰度、无流入；μ指初始质量归一化，不能用Mg/(Mg+Mlocked)偷换。没有选择性富金属风。", "scene": true, "ref": "10.4 · MBW (2010) pp.490–491", "formulaTex": ["\\eta=\\frac\\lambda{1-R},\\quad R=0.4", "Z=\\frac{y}{1+\\eta}\\ln\\frac1\\mu", "\\frac{M_{\\mathrm{locked}}}{M_0}=\\frac{1-\\mu}{1+\\eta}", "M_{\\mathrm{out}}=\\eta M_{\\mathrm{locked}}"]}, {"id": "inflow", "model": "inflow", "title": "流入补回的，是哪一部分气体", "intro": "按作者勘误保持气体质量恒定：只需补回被永久锁定的部分，不能再把已经回流的气体补一次。", "params": [{"key": "dep", "label": "Mgas / Ψ（Gyr）", "min": 0.5, "max": 5, "step": 0.1, "value": 2, "digits": 2}, {"key": "R", "label": "瞬时回流率 R", "min": 0.2, "max": 0.5, "step": 0.01, "value": 0.4, "digits": 2}, {"key": "time", "label": "经过时间（Gyr）", "min": 0, "max": 10, "step": 0.1, "value": 3, "digits": 2}], "values": ["气体 Z", "维持恒定Mg的 A / Ψ", "金属增长 e折时间（Gyr）"], "pages": [490, 492], "formula": "A=(1−R)Ψ，W=0<br>Z(t)=y[1−exp(−(1−R)Ψt/Mgas)]", "assumptions": "按作者p490勘误；原初流入、Zinit=0、y=0.02，Ψ/Mgas与R固定。真实延迟回收、Ia时间分布、径向流与不均匀混合未求解。", "scene": true, "ref": "10.4 · MBW (2010) pp.490–492", "sweep": "time", "formulaTex": ["A=(1-R)\\Psi,\\quad W=0", "Z(t)=y\\left[1-e^{-(1-R)\\Psi t/M_g}\\right]", "\\frac{M_{\\mathrm{locked}}(t)}{M_g}=\\frac{(1-R)t}{t_{\\mathrm{dep}}}"]}], "sections": [{"id": "structure", "num": "10.1", "title": "恒星的结构方程，连接燃料与光", "pages": [449, 463], "paragraphs": ["流体静力、质量连续、能量产生和输运共同决定恒星结构。状态方程、不透明度、核反应与对流会使简单同源标度失效，均匀球或幂律质量—光度关系只能隔离某个机制。", "主序寿命与动力学、Kelvin–Helmholtz时钟不是同一个量。恒星质量增加不等于可用燃料简单按同样倍数延长寿命。"], "labs": ["lifetime"]}, {"id": "tracks", "num": "10.2", "title": "离开主序后，光并没有消失", "pages": [463, 470], "paragraphs": ["前主序收缩、主序燃烧、巨星与渐近巨星支、质量损失和终末遗迹，是不同阶段。转折质量能约束年龄，但观测光也可能由少量明亮的后主序恒星主导。", "超新星前身、双星演化与不同遗迹通道需要更具体的轨迹与反应模型。下面的主序积分故意不冒充完整演化库。"], "labs": ["ssp"]}, {"id": "synthesis", "num": "10.3", "title": "观测光，是形成史与响应的叠加", "pages": [470, 485], "paragraphs": ["星族合成把IMF、恒星轨迹、谱库和形成史连接起来。不同波段响应时间不同，质量加权与光度加权年龄也不同。缺少后主序阶段会给晚期光度带来明显偏差。", "颜色和谱线同时受年龄、金属丰度和尘埃影响。按作者p475勘误，高金属丰度的恒星在HR图上更冷更暗，不能概括为“全部更快演化”。K修正处理观测波段与红移，E修正处理族群演化，两者不可混为一谈。", "气体发射、尘埃红外与Hα/UV形成率标定还依赖电离、IMF和时间平均。反演形成史通常有简并，不能仅凭一条连续谱指定唯一历史。"], "labs": ["sfh", "dust"]}, {"id": "chemistry", "num": "10.4", "title": "把回收、产额和流动放进质量账", "pages": [486, 492], "paragraphs": ["即时回收近似将短寿命恒星的回流快速返回气体，净产额则按永久锁定质量定义。混合假设使气体被视为一个化学箱；真实丰度梯度和散布超出这一模型。", "封闭箱、井混合外流与原初流入，会产生不同的有效产额和恒星金属分布。延迟Ia与元素产额又使α/Fe成为时间线索，但它不唯一指定形成时标。"], "labs": ["closed", "leaky", "inflow"]}, {"id": "feedback", "num": "10.5", "title": "恒星族，同时是能源与物质源", "pages": [492, 494], "paragraphs": ["星风、超新星、金属与质量返回必须与同一IMF和形成史相容。把每次事件的能量加总，只得到能量供应，不等于气体必然以相同效率逃出势阱。", "第8章的爆炸与风泡隔离反馈传播，本章提供源项预算。真实耦合还取决于辐射损失、几何、密度与质量负载，不能由一个能量比包办。"], "labs": []}], "quiz": [{"q": "离开主序的恒星，对完整星族光度一定没有贡献吗？", "options": ["有可能仍很明亮", "一定为零"], "answer": 0, "why": "巨星、AGB等被主序教学积分遗漏。"}, {"q": "相同形成史下，光加权年龄通常比质量加权年龄怎样？", "options": ["更年轻", "必定完全相同"], "answer": 0, "why": "年轻恒星的单位质量光度通常更高；本页用响应核隔离这一效应。"}, {"q": "本页产额y按什么归一？", "options": ["永久锁定的恒星质量", "每个时刻的气体质量"], "answer": 0, "why": "这是封闭箱与流动方程使用的净产额约定。"}, {"q": "R=0.4时保持Mg不变，原初流入A应为多少？", "options": ["Ψ", "0.6Ψ"], "answer": 1, "why": "流入补回的是(1−R)Ψ，已返回的气体不能重复补给。"}, {"q": "外流模型中的μ是什么？", "options": ["Mg/Mg,initial", "Mg/(Mg+Mlocked)"], "answer": 0, "why": "两种比例不同，后者不能直接放入本页对数公式。"}, {"q": "连续谱变红，能否唯一说明恒星更老？", "options": ["能", "不能，还存在尘埃和金属丰度等简并"], "answer": 1, "why": "独立谱线、波段与物理约束有助于区分因素。"}], "errata": "已纳入p475年龄—金属丰度解释及p490流入率勘误；所有简化星谱与响应核都与真实SPS库区分。"};
window.BookSources={"chapter-10": {"title": "恒星族与化学演化", "pages": "449–494", "pdf": "471–516", "section": "第10章", "body": "原创交互导读，覆盖本章主节与精选定量模型；不复刻原书全文、原图或全部推导。各实验的背景与近似分别声明，不组成一套统一研究模拟。伴读生成可复制的参数化问题，未提供在线模型回答。"}, "structure": {"title": "恒星的结构方程，连接燃料与光", "pages": "449–463", "pdf": "471–485", "section": "10.1", "body": "流体静力、质量连续、能量产生和输运共同决定恒星结构。状态方程、不透明度、核反应与对流会使简单同源标度失效，均匀球或幂律质量—光度关系只能隔离某个机制。 主序寿命与动力学、Kelvin–Helmholtz时钟不是同一个量。恒星质量增加不等于可用燃料简单按同样倍数延长寿命。 以上为原创导读，不是原书全文。"}, "tracks": {"title": "离开主序后，光并没有消失", "pages": "463–470", "pdf": "485–492", "section": "10.2", "body": "前主序收缩、主序燃烧、巨星与渐近巨星支、质量损失和终末遗迹，是不同阶段。转折质量能约束年龄，但观测光也可能由少量明亮的后主序恒星主导。 超新星前身、双星演化与不同遗迹通道需要更具体的轨迹与反应模型。下面的主序积分故意不冒充完整演化库。 以上为原创导读，不是原书全文。"}, "synthesis": {"title": "观测光，是形成史与响应的叠加", "pages": "470–485", "pdf": "492–507", "section": "10.3", "body": "星族合成把IMF、恒星轨迹、谱库和形成史连接起来。不同波段响应时间不同，质量加权与光度加权年龄也不同。缺少后主序阶段会给晚期光度带来明显偏差。 颜色和谱线同时受年龄、金属丰度和尘埃影响。按作者p475勘误，高金属丰度的恒星在HR图上更冷更暗，不能概括为“全部更快演化”。K修正处理观测波段与红移，E修正处理族群演化，两者不可混为一谈。 气体发射、尘埃红外与Hα/UV形成率标定还依赖电离、IMF和时间平均。反演形成史通常有简并，不能仅凭一条连续谱指定唯一历史。 以上为原创导读，不是原书全文。"}, "chemistry": {"title": "把回收、产额和流动放进质量账", "pages": "486–492", "pdf": "508–514", "section": "10.4", "body": "即时回收近似将短寿命恒星的回流快速返回气体，净产额则按永久锁定质量定义。混合假设使气体被视为一个化学箱；真实丰度梯度和散布超出这一模型。 封闭箱、井混合外流与原初流入，会产生不同的有效产额和恒星金属分布。延迟Ia与元素产额又使α/Fe成为时间线索，但它不唯一指定形成时标。 以上为原创导读，不是原书全文。"}, "feedback": {"title": "恒星族，同时是能源与物质源", "pages": "492–494", "pdf": "514–516", "section": "10.5", "body": "星风、超新星、金属与质量返回必须与同一IMF和形成史相容。把每次事件的能量加总，只得到能量供应，不等于气体必然以相同效率逃出势阱。 第8章的爆炸与风泡隔离反馈传播，本章提供源项预算。真实耦合还取决于辐射损失、几何、密度与质量负载，不能由一个能量比包办。 以上为原创导读，不是原书全文。"}, "lifetime": {"title": "用主序寿命，读一群恒星的年龄", "pages": "462–463", "pdf": "484–485", "section": "10.1 · MBW (2010) pp.462–463", "body": "原书式10.72的近太阳丰度寿命拟合，0.08–100M☉内求转折。显示L∝m³·⁵只是独立教学标度，不是该拟合自带精确光度。未加入旋转、双星或完整演化轨迹。"}, "ssp": {"title": "一场形成之后，哪些主序星仍在发光", "pages": "470–474", "pdf": "492–496", "section": "10.2 · MBW (2010) pp.470–474", "body": "仅主序星加权模型，遗漏巨星、AGB、双星、遗迹光、金属丰度与真实恒星谱。因此晚期光度不能代替SPS数据库；离开主序的质量也不等于已经全部回到气体。"}, "sfh": {"title": "光更年轻，还是恒星质量更年轻", "pages": "471–474", "pdf": "493–496", "section": "10.3 · MBW (2010) pp.471–474", "body": "总形成质量归一化为1，两个指数函数都是明确指定的教学形状。曲线权重各自面积归一，光响应不对应实际滤镜；不能从此推断观测年龄精度。 响应核在年龄为0时定义为1，未指定实际波段或太阳光度单位。"}, "dust": {"title": "同一束光，被尘埃怎样改写", "pages": "476–484", "pdf": "498–506", "section": "10.3 · MBW (2010) pp.476–484", "body": "单温黑体不是星族光谱。积分直达光损失只涵盖0.15–2.5μm；消光包含吸收和散射出视线，模型未分离两者，因此该损失不等于被吸收能量，也未计算红外再辐射。B/V用0.44/0.55μm窄带近似；真实衰减还依赖混合几何、散射和尘埃性质。 A_B表示B波段消光，不是AB星等系统；E(B−V)=A_B−A_V。"}, "closed": {"title": "封闭箱里，气体越少越富金属", "pages": "486–490", "pdf": "508–512", "section": "10.4 · MBW (2010) pp.486–490", "body": "初始Z=0、瞬时回收与均匀混合，无流入流出。y按永久锁定质量定义，非每单位总形成质量；金属质量分数Z不是直接的[Fe/H]。 μ=1时没有已锁定恒星，恒星平均金属丰度不定义；0仅是从有恒星侧趋近的极限。"}, "leaky": {"title": "同样的产额，外流为何降低有效产额", "pages": "490–491", "pdf": "512–513", "section": "10.4 · MBW (2010) pp.490–491", "body": "外流与星际气体同丰度、无流入；μ指初始质量归一化，不能用Mg/(Mg+Mlocked)偷换。没有选择性富金属风。"}, "inflow": {"title": "流入补回的，是哪一部分气体", "pages": "490–492", "pdf": "512–514", "section": "10.4 · MBW (2010) pp.490–492", "body": "按作者p490勘误；原初流入、Zinit=0、y=0.02，Ψ/Mgas与R固定。真实延迟回收、Ia时间分布、径向流与不均匀混合未求解。"}};
